/**
 * @description Tests for the IH_SampleConnectionAuth template: the login sets the Authorization header, the token is
 * reused from the cache, a refresh logs in again, a refused login or an answer without a token throws, and a token URL
 * that is down throws a CalloutException (temporary).
 */
@IsTest
private class IH_SampleConnectionAuthTest {

    private static final String USER_DOMAIN = '@ihsampleauth.example.com';

    @TestSetup
    static void setup() {
        List<Profile> profiles = [SELECT Id FROM Profile WHERE Name = 'Standard User' WITH SYSTEM_MODE LIMIT 1];
        Id profileId = profiles.isEmpty() ? UserInfo.getProfileId() : profiles[0].Id;
        String unique = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(10);
        User tester = new User(LastName = 'IH Sample Tester', Alias = unique.left(8), Email = unique + '@example.com',
            Username = unique + '.auth' + USER_DOMAIN, ProfileId = profileId, EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US', LocaleSidKey = 'en_US', TimeZoneSidKey = 'America/Chicago');
        System.runAs(new User(Id = UserInfo.getUserId())) {
            insert tester;
        }
    }

    private static User tester() {
        String pattern = '%.auth' + USER_DOMAIN;
        return [SELECT Id FROM User WHERE Username LIKE :pattern WITH SYSTEM_MODE LIMIT 1];
    }

    /* A connection Id that is never saved: the cache only needs a key. */
    private static IH_Connection__c connection() {
        String prefix = Schema.IH_Connection__c.SObjectType.getDescribe(SObjectDescribeOptions.DEFERRED).getKeyPrefix();
        return new IH_Connection__c(Id = Id.valueOf(prefix + '000000000001'), Name = 'Partner',
            Connection_Type__c = 'Apex Auth', Auth_Class__c = 'IH_SampleConnectionAuth');
    }

    private static IntegrationHub.AuthContext context(Boolean refresh) {
        IntegrationHub.AuthContext ctx = new IntegrationHub.AuthContext();
        ctx.request = new HttpRequest();
        ctx.connection = connection();
        ctx.refresh = refresh;
        ctx.eventKey = 'PARTNER_ORDER';
        return ctx;
    }

    @IsTest
    static void logsInOnceAndReusesTheToken() {
        System.runAs(tester()) {
            TokenMock mock = new TokenMock(200, '{"access_token":"T-1","expires_in":3600}');
            Test.setMock(HttpCalloutMock.class, mock);
            Test.startTest();
            // The first call refreshes, so a token cached by an earlier run cannot hide the login.
            IntegrationHub.AuthContext first = context(true);
            new IH_SampleConnectionAuth().authorize(first);
            IntegrationHub.AuthContext second = context(false);
            new IH_SampleConnectionAuth().authorize(second);
            IntegrationHub.AuthContext refreshed = context(true);
            new IH_SampleConnectionAuth().authorize(refreshed);
            Test.stopTest();
            Assert.areEqual('Bearer T-1', first.request.getHeader('Authorization'), 'the token is set as a Bearer header');
            Assert.areEqual('Bearer T-1', second.request.getHeader('Authorization'), 'the cached token is used');
            Assert.areEqual('Bearer T-1', refreshed.request.getHeader('Authorization'), 'a refresh sets the new token');
            Assert.areEqual(2, mock.calls, 'a login, the cached token, then one more login for the refresh');
            Assert.isTrue(mock.lastBody.contains('grant_type=client_credentials'), 'the login asks for a token');
        }
    }

    @IsTest
    static void refusedLoginThrows() {
        System.runAs(tester()) {
            Test.setMock(HttpCalloutMock.class, new TokenMock(401, '{"error":"invalid_client"}'));
            String message;
            Test.startTest();
            try {
                // Refresh, so a token kept in Platform Cache by an earlier run cannot hide the login.
                new IH_SampleConnectionAuth().authorize(context(true));
            } catch (IntegrationHub.HubException e) {
                message = e.getMessage();
            }
            Test.stopTest();
            Assert.isTrue(message.contains('HTTP 401'), 'the refused login is explained: ' + message);
        }
    }

    @IsTest
    static void tokenUrlDownIsACalloutError() {
        System.runAs(tester()) {
            Test.setMock(HttpCalloutMock.class, new TokenMock(503, 'unavailable'));
            String message;
            Test.startTest();
            try {
                new IH_SampleConnectionAuth().authorize(context(true));
            } catch (CalloutException e) {
                message = e.getMessage();
            }
            Test.stopTest();
            Assert.isTrue(message.contains('HTTP 503'), 'a token URL that is down is a callout error (temporary): ' + message);
        }
    }

    @IsTest
    static void answerWithoutTokenThrows() {
        System.runAs(tester()) {
            Test.setMock(HttpCalloutMock.class, new TokenMock(200, '{"token_type":"bearer"}'));
            String message;
            Test.startTest();
            try {
                new IH_SampleConnectionAuth().authorize(context(true));
            } catch (IntegrationHub.HubException e) {
                message = e.getMessage();
            }
            Test.stopTest();
            Assert.isTrue(message.contains('access_token'), 'a missing token is explained: ' + message);
        }
    }

    @IsTest
    static void readsExpiresIn() {
        System.runAs(tester()) {
            Assert.areEqual(3600, IH_SampleConnectionAuth.secondsOf(null), 'missing: one hour');
            Assert.areEqual(120, IH_SampleConnectionAuth.secondsOf('120'), 'a text number');
            Assert.areEqual(90, IH_SampleConnectionAuth.secondsOf(90), 'a number');
            Assert.areEqual(3600, IH_SampleConnectionAuth.secondsOf('soon'), 'not a number: one hour');
            Assert.isNull(IH_SampleConnectionAuth.parse('[1]'), 'not an object');
            Assert.isNull(IH_SampleConnectionAuth.parse('not json'), 'not JSON');
        }
    }

    /**
     * @description Token URL mock that counts the logins.
     */
    private class TokenMock implements HttpCalloutMock {
        private final Integer code;
        private final String body;
        Integer calls = 0;
        String lastBody;

        TokenMock(Integer statusCode, String replyBody) {
            code = statusCode;
            body = replyBody;
        }

        /**
         * @description Answers the login.
         * @param req the request
         * @return the answer
         */
        public HttpResponse respond(HttpRequest req) {
            calls++;
            lastBody = req.getBody();
            HttpResponse res = new HttpResponse();
            res.setStatusCode(code);
            res.setBody(body);
            return res;
        }
    }
}
